def s(key, fr_l, fr_d, en_l, en_d):
    a('SET_' + key, fr_l, en_l); a('SET_%s_DESC' % key, fr_d, en_d)
s('ADMIN_EMAIL', "E-mail d'alerte administrateur", "Adresse qui reçoit l'alerte « nouvelle précommande ». Vide = adresse d'expéditeur du site.", 'Administrator alert email', 'Address receiving the "new pre-order" alert. Empty = the site sender address.')
