# Messages pluriels générés par AdminController (suffixes _0, _1, _MORE selon la langue)
for _p in ('RULES', 'SUBSCRIBERS'):
    for _a, _fr, _en in (('DELETED', 'supprimé(s)', 'deleted'), ('PUBLISHED', 'activé(s)', 'enabled'), ('UNPUBLISHED', 'désactivé(s)', 'disabled')):
        for _s, _n in (('0', 'Aucun élément'), ('1', '1 élément'), ('MORE', '%d éléments')):
            _en_n = {'0': 'No item', '1': '1 item', 'MORE': '%d items'}[_s]
            K['COM_WEBSOURCEPREORDER_%s_N_ITEMS_%s_%s' % (_p, _a, _s)] = ('%s %s.' % (_n, _fr), '%s %s.' % (_en_n, _en))
            K['COM_WEBSOURCEPREORDER_%s_N_ITEMS_%s' % (_p, _a)] = ('%d élément(s) ' + _fr + '.', '%d item(s) ' + _en + '.')
